    /* ============================================================
       DESIGN VARIANCE: 9  |  MOTION_INTENSITY: 7  |  DENSITY: 312313
       Playful / funny / anti-perfection single-page comedy site
       ============================================================ */

    * { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --yellow: #ffe74c;
      --pink:   #ff6b9d;
      --blue:   #4ecdc4;
      --bg:     #1a1a2e;
      --card:   #16213e;
      --text:   #eaeaea;
    }

    body {
      font-family: 'Comic Sans MS', 'Chalkboard SE', 'Segoe Print', cursive, sans-serif;
      background: var(--bg);
      color: var(--text);
      min-height: 100vh;
      overflow-x: hidden;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 2rem 1rem;
    }

    /* --- Hero section --- */
    .hero {
      text-align: center;
      margin-bottom: 2rem;
      position: relative;
    }

    .hero h1 {
      font-size: clamp(2.5rem, 8vw, 5rem);
      background: linear-gradient(135deg, var(--yellow), var(--pink), var(--blue));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      line-height: 1.2;
      animation: wobble 2s ease-in-out infinite alternate;
      filter: drop-shadow(0 4px 12px rgba(255,107,157,.35));
    }

    .hero .subtitle {
      font-size: clamp(1rem, 3vw, 1.5rem);
      margin-top: 0.5rem;
      opacity: 0.85;
      animation: fadeSlideUp 0.8s ease-out;
    }

    .hero .subtitle::after {
      content: " 馃憜 浣嗚涓嶅ソ";
      font-size: 0.7em;
      opacity: 0.5;
    }

    /* --- Joke card --- */
    .joke-box {
      width: 100%;
      max-width: 600px;
      margin: 1rem auto;
      padding: 2rem 1.5rem;
      border-radius: 40px 12px 40px 12px;
      background: var(--card);
      border: 2px dashed var(--yellow);
      text-align: center;
      transition: border-radius 0.3s;
      position: relative;
    }

    .joke-box:hover {
      border-radius: 12px 40px 12px 40px;
    }

    .joke-text {
      font-size: 1.4rem;
      line-height: 1.6;
      min-height: 4.5rem;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0.5rem;
      transition: opacity 0.3s;
    }

    .joke-text.fading {
      opacity: 0;
      transform: scale(0.92);
    }

    .joke-emoji {
      font-size: 4rem;
      display: block;
      margin-bottom: 0.8rem;
      animation: float 2.5s ease-in-out infinite;
