        emojiEl.textContent = item.emoji;

        // Fade in
        jokeEl.classList.remove('fading');
        emojiEl.style.opacity = '1';

        // Stats
        laughCount++;
        laughEl.textContent = laughCount;
        updateFunLevel();

        // Confetti every 5 laughs
        if (laughCount % 5 === 0) {
          spawnConfetti();
        }

        isTransitioning = false;
      }, 250);
    }

    // ================================================================
    // TICKER
    // ================================================================
    let tickerIdx = -1;
    function rotateFact() {
      const { item, index } = randomItem(funFacts, tickerIdx);
      tickerIdx = index;
      tickerEl.style.opacity = '0';
      setTimeout(() => {
        tickerEl.textContent = item;
        tickerEl.style.opacity = '1';
      }, 250);
    }

    // Init ticker
    (function initTicker() {
      tickerIdx = Math.floor(Math.random() * funFacts.length);
      tickerEl.textContent = funFacts[tickerIdx];
      setInterval(rotateFact, 4000);
    })();

    // ================================================================
    // EASTER EGG
    // ================================================================
    eggZone.addEventListener('click', () => {
      eggClicks++;
      eggCountEl.textContent = eggClicks;
      if (eggClicks >= 5) {
        eggZone.classList.add('secret-visible');
        spawnConfetti();
      }
    });

    // ================================================================
    // EVENT BINDING
    // ================================================================
    document.getElementById('jokeBtn').addEventListener('click', showJoke);

    // Keyboard shortcut: spacebar = joke
    document.addEventListener('keydown', (e) => {
      if (e.code === 'Space' && !e.repeat && !['INPUT', 'TEXTAREA'].includes(e.target.tagName)) {
        e.preventDefault();
        showJoke();
      }
    });

    // ================================================================
    // BOOT: show a random joke on load
    // ================================================================
    showJoke();

    console.log('%c馃寶 涓嶆缁忕綉椤靛凡鍔犺浇', 'font-size:2rem;');
    console.log('%c璇曡瘯鎸?绌烘牸閿?蹇€熸悶绗?, 'font-size:1.2rem; color:#ffe74c;');
    console.log('%c鎴栬€呯偣閭ｄ釜寰堜笐鐨勬寜閽?, 'font-size:1.2rem; color:#ff6b9d;');
  </script>
